// 明确认可和条件控制分开，原S3模板全验是本组件之外的前置。
#include "resident/domains/family/collateral_control_catalog.hpp"
#include "resident/checkpoint/ordered_value.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {Integer checks=0;void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}}
int main(){try{auto parsed=parse_boundary_json(R"({"version":1,"profile":"recognized_collateral_control_v1","requests":[{"id":"request","template_id":"template","recognize_node_id":"recognize","accept_node_id":"accept","revoke_node_id":"revoke","terms_version":1,"recognition_scope":"mutual_collateral_recognition_only","control_scope":"own_life_control_only"}]})");check(parsed.ok,"original explicit policy JSON");auto read=decode_collateral_control_catalog(parsed.value);check(read.ok,"three distinct declarations decode");const auto original=read.value;auto common=std::make_shared<CommonCatalog>();InteractionCatalog interactions;interactions.common=common;DialogueDefinition d;d.id="dialogue";for(const auto* id:{"recognize","accept","revoke"}){DialogueNode n;n.id=id;n.kind="say";n.speaker="$provider";d.nodes.push_back(n);}interactions.dialogues.push_back(d);LegacyControlConsentCatalog legacy;legacy.enabled=true;legacy.version=3;KnownPersonalDialogueTemplate t{"template","dialogue",{"installed_actor","first"},{"born_prototype","child"}};CollateralControlTemplateRead templates=[&](const StableId&)->Outcome<KnownPersonalDialogueTemplate>{return {true,t,{}};};check(validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"original Known template provider declarations");
 for(const auto* speaker:{"$player","someone"}){interactions.dialogues[0].nodes[0].speaker=speaker;check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"other speaker cannot recognize provider kinship");}interactions.dialogues[0].nodes[0].speaker="$provider";interactions.dialogues[0].nodes[1].kind="choice";check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"choice cannot grant control");interactions.dialogues[0].nodes[1].kind="say";auto bad=original;bad.definitions.find("request")->accept_node_id="recognize";check(!validate_collateral_control_catalog(bad,legacy,interactions,templates).ok,"recognition cannot double as control consent");bad=original;bad.definitions.find("request")->revoke_node_id="missing";check(!validate_collateral_control_catalog(bad,legacy,interactions,templates).ok,"actual withdrawal node required");legacy.version=2;check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"old Legacy2 cannot enable new source");legacy.version=3;check(!validate_collateral_control_catalog(original,legacy,interactions,{}).ok,"missing real template read refused");t.id="other";check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"wrong selected template refused");t.id="template";interactions.dialogues[0].context_role="some_role";check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"not a role impersonation entry");interactions.dialogues[0].context_role.clear();legacy.definitions.insert("request",{});check(!validate_collateral_control_catalog(original,legacy,interactions,templates).ok,"original control request cannot be shadowed");
 auto bad_json=parsed.value;*bad_json.find("requests")->as<BoundaryValue::Array>()->front().find("control_scope")=BoundaryValue{"all_assets"};check(!decode_collateral_control_catalog(bad_json).ok,"no asset rights in control policy");bad_json=parsed.value;bad_json.as<BoundaryValue::Dict>()->push_back({"version",BoundaryValue{Integer{1}}});check(!decode_collateral_control_catalog(bad_json).ok,"duplicate field refused");bad_json=parsed.value;*bad_json.find("requests")->as<BoundaryValue::Array>()->front().find("accept_node_id")=BoundaryValue{"recognize"};check(!decode_collateral_control_catalog(bad_json).ok,"same sentence cannot silently combine decisions");
 std::cout<<"COLLATERAL_CONTROL_CATALOG "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
